class Car:
    def __init__(self, make, model, miles):
        self.make = make
        self.model = model
        self._miles = 0
        self.miles = miles

    @property
    def miles(self):
        return self._miles

    @miles.setter
    def miles(self, value):
        if value >= 0:
            self._miles = value

